#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXH 105
#define MAXW 105
#define MAXC 100005

typedef struct {
    int r, c, d, step;
} State;

char grid[MAXH][MAXW + 5];
char cmd[MAXC];
int visited[MAXH][MAXW][4];

int dr[4] = {-1, 0, 1, 0}; // N, E, S, W
int dc[4] = {0, 1, 0, -1};

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    int sr = -1, sc = -1, er = -1, ec = -1;

    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'S') {
                sr = i; sc = j;
                grid[i][j] = '.';
            } else if (grid[i][j] == 'E') {
                er = i; ec = j;
                grid[i][j] = '.';
            }
        }
    }

    scanf("%s", cmd);
    int n = (int)strlen(cmd);

    State *q = (State *)malloc(sizeof(State) * H * W * 4 * (n + 1 > 1 ? 1 : 1));
    int front = 0, back = 0;

    for (int d = 0; d < 4; d++) {
        visited[sr][sc][d] = 1;
        q[back++] = (State){sr, sc, d, 0};
    }

    while (front < back) {
        State cur = q[front++];

        if (cur.r == er && cur.c == ec) {
            printf("Yes\n");
            free(q);
            return 0;
        }

        if (cur.step == n) continue;

        char ch = cmd[cur.step];

        if (ch == 'L') {
            int nd = (cur.d + 3) % 4;
            if (!visited[cur.r][cur.c][nd]) {
                visited[cur.r][cur.c][nd] = 1;
                q[back++] = (State){cur.r, cur.c, nd, cur.step + 1};
            }
        } else if (ch == 'R') {
            int nd = (cur.d + 1) % 4;
            if (!visited[cur.r][cur.c][nd]) {
                visited[cur.r][cur.c][nd] = 1;
                q[back++] = (State){cur.r, cur.c, nd, cur.step + 1};
            }
        } else if (ch == 'F') {
            int nr = cur.r + dr[cur.d];
            int nc = cur.c + dc[cur.d];
            if (0 <= nr && nr < H && 0 <= nc && nc < W && grid[nr][nc] != '#') {
                if (!visited[nr][nc][cur.d]) {
                    visited[nr][nc][cur.d] = 1;
                    q[back++] = (State){nr, nc, cur.d, cur.step + 1};
                }
            }
        } else if (ch == '?') {
            // Turn left
            int nd = (cur.d + 3) % 4;
            if (!visited[cur.r][cur.c][nd]) {
                visited[cur.r][cur.c][nd] = 1;
                q[back++] = (State){cur.r, cur.c, nd, cur.step + 1};
            }

            // Turn right
            nd = (cur.d + 1) % 4;
            if (!visited[cur.r][cur.c][nd]) {
                visited[cur.r][cur.c][nd] = 1;
                q[back++] = (State){cur.r, cur.c, nd, cur.step + 1};
            }

            // Move forward
            int nr = cur.r + dr[cur.d];
            int nc = cur.c + dc[cur.d];
            if (0 <= nr && nr < H && 0 <= nc && nc < W && grid[nr][nc] != '#') {
                if (!visited[nr][nc][cur.d]) {
                    visited[nr][nc][cur.d] = 1;
                    q[back++] = (State){nr, nc, cur.d, cur.step + 1};
                }
            }
        }
    }

    printf("No\n");
    free(q);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;

    vector<string> grid(H);
    int start_r = -1, start_c = -1;
    int end_r = -1, end_c = -1;

    for (int i = 0; i < H; i++) {
        cin >> grid[i];
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'S') {
                start_r = i;
                start_c = j;
            } else if (grid[i][j] == 'G') {
                end_r = i;
                end_c = j;
            }
        }
    }

    string commands;
    cin >> commands;

    // Directions: 0=up, 1=right, 2=down, 3=left
    int dr[4] = {-1, 0, 1, 0};
    int dc[4] = {0, 1, 0, -1};

    // BFS state: (row, col, dir, cmd_index)
    // We'll use a set to avoid revisiting same state
    struct State {
        int r, c, dir, idx;
        bool operator<(const State& other) const {
            if (r != other.r) return r < other.r;
            if (c != other.c) return c < other.c;
            if (dir != other.dir) return dir < other.dir;
            return idx < other.idx;
        }
    };

    queue<State> q;
    set<State> visited;

    // Start in all 4 directions at command index 0
    for (int d = 0; d < 4; d++) {
        State s = {start_r, start_c, d, 0};
        q.push(s);
        visited.insert(s);
    }

    while (!q.empty()) {
        State cur = q.front();
        q.pop();

        int r = cur.r, c = cur.c, dir = cur.dir, idx = cur.idx;

        // Check if reached goal
        if (r == end_r && c == end_c) {
            cout << "Yes\n";
            return 0;
        }

        // If no more commands, we can't move further
        if (idx == (int)commands.size()) {
            continue;
        }

        char cmd = commands[idx];

        if (cmd == 'F') {
            // Move forward
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            if (nr >= 0 && nr < H && nc >= 0 && nc < W && grid[nr][nc] != '#') {
                State ns = {nr, nc, dir, idx + 1};
                if (visited.find(ns) == visited.end()) {
                    visited.insert(ns);
                    q.push(ns);
                }
            } else {
                // Can't move forward, stay in place but advance command
                State ns = {r, c, dir, idx + 1};
                if (visited.find(ns) == visited.end()) {
                    visited.insert(ns);
                    q.push(ns);
                }
            }
        } else if (cmd == 'L') {
            // Turn left
            int ndir = (dir + 3) % 4;
            State ns = {r, c, ndir, idx + 1};
            if (visited.find(ns) == visited.end()) {
                visited.insert(ns);
                q.push(ns);
            }
        } else if (cmd == 'R') {
            // Turn right
            int ndir = (dir + 1) % 4;
            State ns = {r, c, ndir, idx + 1};
            if (visited.find(ns) == visited.end()) {
                visited.insert(ns);
                q.push(ns);
            }
        }
    }

    cout << "No\n";
    return 0;
}

