#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    if (!(cin >> H >> W)) return 0;

    vector<string> grid(H);
    for (int i = 0; i < H; ++i) cin >> grid[i];

    string cmd;
    cin >> cmd;

    pair<int,int> S{-1,-1}, E{-1,-1};
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (grid[i][j] == 'S') S = {i, j};
            if (grid[i][j] == 'E') E = {i, j};
        }
    }

    // Directions: 0=up, 1=right, 2=down, 3=left
    int dr[4] = {-1, 0, 1, 0};
    int dc[4] = {0, 1, 0, -1};

    // visited[r][c][dir][k]: reachable after processing first k commands
    // Optimize by keeping only current states.
    vector<vector<array<bool,4>>> cur(H, vector<array<bool,4>>(W, {false,false,false,false}));
    vector<vector<array<bool,4>>> nxt(H, vector<array<bool,4>>(W, {false,false,false,false}));

    // Initial direction is not specified, so allow all 4 directions.
    for (int d = 0; d < 4; ++d) cur[S.first][S.second][d] = true;

    auto is_free = [&](int r, int c) {
        return 0 <= r && r < H && 0 <= c && c < W && grid[r][c] != '#';
    };

    for (char ch : cmd) {
        for (int i = 0; i < H; ++i)
            for (int j = 0; j < W; ++j)
                nxt[i][j] = {false,false,false,false};

        for (int r = 0; r < H; ++r) {
            for (int c = 0; c < W; ++c) {
                for (int d = 0; d < 4; ++d) {
                    if (!cur[r][c][d]) continue;

                    if (ch == 'L') {
                        nxt[r][c][(d + 3) % 4] = true;
                    } else if (ch == 'R') {
                        nxt[r][c][(d + 1) % 4] = true;
                    } else { // Forward, assume 'F'
                        int nr = r + dr[d], nc = c + dc[d];
                        if (is_free(nr, nc)) nxt[nr][nc][d] = true;
                    }
                }
            }
        }
        cur.swap(nxt);
    }

    bool ok = false;
    for (int d = 0; d < 4; ++d) {
        if (cur[E.first][E.second][d]) ok = true;
    }

    cout << (ok ? "Yes" : "No") << '\n';
    return 0;
}

