public class RobotMaze {
    static int[] dr = {-1, 0, 1, 0}; // N, E, S, W
    static int[] dc = {0, 1, 0, -1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        sc.nextLine();

        char[][] grid = new char[H][W];
        int startR = -1, startC = -1, endR = -1, endC = -1;

        for (int i = 0; i < H; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < W; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == 'G') {
                    endR = i;
                    endC = j;
                }
            }
        }

        String commands = sc.nextLine();

        // Find initial direction: check 4 neighbors for an empty cell or G
        int dir = -1;
        for (int d = 0; d < 4; d++) {
            int nr = startR + dr[d];
            int nc = startC + dc[d];
            if (nr >= 0 && nr < H && nc >= 0 && nc < W && (grid[nr][nc] == '.' || grid[nr][nc] == 'G')) {
                dir = d;
                break;
            }
        }

        int r = startR, c = startC;
        boolean reached = (r == endR && c == endC);

        for (char cmd : commands.toCharArray()) {
            if (cmd == 'L') {
                dir = (dir + 3) % 4;
            } else if (cmd == 'R') {
                dir = (dir + 1) % 4;
            } else if (cmd == 'F') {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W && grid[nr][nc] != '#') {
                    r = nr;
                    c = nc;
                }
            }
            if (r == endR && c == endC) {
                reached = true;
                break;
            }
        }

        System.out.println(reached ? "Yes" : "No");
        sc.close();
    }
}

