import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static final int[] DR = {-1, 0, 1, 0}; // N,E,S,W
    static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;
        int H = Integer.parseInt(first);
        int W = fs.nextInt();

        char[][] grid = new char[H][W];
        int sr = -1, sc = -1, er = -1, ec = -1;

        for (int i = 0; i < H; i++) {
            String row = fs.next();
            while (row.length() < W) row += fs.next();
            for (int j = 0; j < W; j++) {
                char ch = row.charAt(j);
                grid[i][j] = ch;
                if (ch == 'S' || ch == 's') {
                    sr = i; sc = j;
                    grid[i][j] = '.';
                } else if (ch == 'E' || ch == 'e') {
                    er = i; ec = j;
                    grid[i][j] = '.';
                }
            }
        }

        String commands = fs.next();
        if (commands == null) commands = "";

        // If start/end are not explicitly marked, try common alternatives:
        // entrance/exit may be represented by two non-wall border cells.
        if (sr == -1 || er == -1) {
            List<int[]> borderOpen = new ArrayList<>();
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (i == 0 || i == H - 1 || j == 0 || j == W - 1) {
                        if (grid[i][j] != '#') borderOpen.add(new int[]{i, j});
                    }
                }
            }
            if (sr == -1 && borderOpen.size() >= 1) {
                sr = borderOpen.get(0)[0];
                sc = borderOpen.get(0)[1];
            }
            if (er == -1 && borderOpen.size() >= 2) {
                er = borderOpen.get(1)[0];
                ec = borderOpen.get(1)[1];
            }
        }

        // BFS on state: row, col, dir, idx in commands
        // dir matters because turns affect future moves.
        boolean[][][][] vis = new boolean[H][W][4][commands.length() + 1];
        ArrayDeque<int[]> q = new ArrayDeque<>();

        for (int d = 0; d < 4; d++) {
            vis[sr][sc][d][0] = true;
            q.add(new int[]{sr, sc, d, 0});
        }

        boolean ok = false;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], dir = cur[2], idx = cur[3];

            if (r == er && c == ec) {
                ok = true;
                break;
            }
            if (idx == commands.length()) continue;

            char cmd = commands.charAt(idx);
            int nr = r, nc = c, nd = dir;

            if (cmd == 'L' || cmd == 'l') {
                nd = (dir + 3) % 4;
            } else if (cmd == 'R' || cmd == 'r') {
                nd = (dir + 1) % 4;
            } else {
                // Treat any other forward-like command as move forward
                nr = r + DR[dir];
                nc = c + DC[dir];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W || grid[nr][nc] == '#') {
                    nr = r;
                    nc = c;
                }
            }

            if (!vis[nr][nc][nd][idx + 1]) {
                vis[nr][nc][nd][idx + 1] = true;
                q.add(new int[]{nr, nc, nd, idx + 1});
            }
        }

        System.out.println(ok ? "Yes" : "No");
    }
}
